/* ===================== BÀI 25 · Timer 0/1 và chế độ hoạt động ===================== */
/* Bài 25 · Timer 0/1 và chế độ hoạt động (AMTS-EMB-001-M07-L01, MC51-025) — sinh bởi tools/author/mcu8051/l25.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR25=[{"label":"Ví dụ: Timer 0 chế độ 1 đếm tới tràn","code":"; Ví dụ 1: Timer 0 chế độ 1 (16 bit) đếm chu kỳ máy tới khi tràn\n; Chip: AT89S52, 12 MHz. TH0:TL0 bắt đầu ở FFF0H: 16 lần đếm\n        ORG     0000H\n        MOV     TMOD,#01H               ; Timer 0: GATE=0, C/T=0, chế độ 1\n        MOV     TH0,#0FFH               ; giá trị nạp FFF0H\n        MOV     TL0,#0F0H\n        SETB    TR0                     ; cho Timer 0 chạy\nCHO:    JNB     TF0,CHO                 ; chờ cờ tràn TF0 = 1\n        CLR     TR0                     ; dừng Timer 0\n        CLR     TF0                     ; phần mềm phải tự xóa cờ\n        SJMP    $\n        END\n","note":"Bấm Từng bước tới SETB TR0 rồi theo dõi TL0: F0H → F1H… mỗi chu kỳ máy +1. Vòng JNB tốn 2 chu kỳ nên TL0 tăng 2 mỗi bước. Lần tràn thứ 16 đưa TH0:TL0 về 0000H và TF0 = 1; CLR TR0 vẫn được đếm thêm 1 nhịp (TL0 = 01H). Tổng: 25 chu kỳ tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chế độ 2 tự nạp, tràn đều mỗi 10 nhịp","code":"; Ví dụ 2: Timer 1 chế độ 2 (8 bit tự nạp), tràn mỗi 10 nhịp\n; Chip: AT89S52, 12 MHz. Mỗi lần tràn đảo LED P1.0, 3 lần\n        ORG     0000H\n        MOV     TMOD,#20H               ; Timer 1: chế độ 2\n        MOV     TH1,#0F6H               ; giá trị nạp lại = 256 - 10\n        MOV     TL1,#0F6H               ; lần đếm đầu cũng 10 nhịp\n        MOV     R7,#3                   ; đếm 3 lần tràn\n        SETB    TR1\nLAP:    JNB     TF1,LAP                 ; chờ tràn\n        CLR     TF1\n        CPL     P1.0                    ; đảo LED P1.0\n        DJNZ    R7,LAP\n        CLR     TR1\n        SJMP    $\n        END\n","note":"TH1 = F6H giữ giá trị nạp; TL1 đếm F6H → FFH → tràn → phần cứng chép F6H vào TL1. Ở phần Thời gian, TF1 bật đúng mỗi 10 chu kỳ máy (chu kỳ 18, 28, 38), LED P1.0 đổi 3 lần. Đoán trước: TL1 khi dừng? (FBH: đếm thêm 5 nhịp sau lần tràn cuối.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Chế độ 0 là bộ đếm 13 bit","code":"; Ví dụ 3: Timer 0 chế độ 0 (13 bit): TH0 8 bit + 5 bit thấp TL0\n; Chip: AT89S52. Số đếm 13 bit = 1 1111 1111 1100B: còn 4 nhịp\n        ORG     0000H\n        MOV     TMOD,#00H               ; Timer 0: chế độ 0\n        MOV     TH0,#0FFH               ; 8 bit cao của số đếm\n        MOV     TL0,#1CH                ; 5 bit thấp = 11100B\n        SETB    TR0\nCHO:    JNB     TF0,CHO\n        MOV     A,TL0                   ; đọc số đếm ngay sau khi tràn\n        MOV     B,TH0\n        CLR     TR0\n        SJMP    $\n        END\n","note":"Chế độ 0 coi TH0 là 8 bit cao và 5 bit thấp của TL0 là phần thấp của số 13 bit: FFH:1CH là 1 1111 1111 1100B, chỉ còn 4 nhịp. Khi 5 bit thấp của TL0 quay về 0, TH0 tăng; TH0 từ FFH lên 00H là tràn, TF0 = 1. Cuối cùng A = 01H, B = 00H (trên chip thật chỉ 5 bit thấp của A, tức TL0, là xác định; 3 bit cao bằng 0 theo mô hình của trình mô phỏng).","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: MOV TMOD ghi đè cấu hình Timer 1","code":"; Ví dụ 4 (bẫy): ghi cả byte TMOD làm hỏng cấu hình Timer 1\n; Chip: AT89S52. TMOD không định địa chỉ bit được\n        ORG     0000H\n        MOV     TMOD,#20H               ; Timer 1 chế độ 2 (đang được dùng)\n        MOV     TMOD,#01H               ; SAI: đặt Timer 0 nhưng xóa Timer 1\n        MOV     30H,TMOD                ; 30H = 01H: Timer 1 về chế độ 0\n        MOV     TMOD,#20H               ; làm lại\n        ANL     TMOD,#0F0H              ; ĐÚNG: chỉ xóa 4 bit của Timer 0\n        ORL     TMOD,#01H               ; rồi đặt Timer 0 chế độ 1\n        MOV     31H,TMOD                ; 31H = 21H: Timer 1 giữ chế độ 2\n        SJMP    $\n        END\n","note":"Lệnh MOV TMOD,#01H ghi cả 8 bit nên nửa của Timer 1 về 0 (chế độ 0): ô 30H = 01H. Cách đúng là ANL TMOD,#0F0H rồi ORL TMOD,#01H: ô 31H = 21H, Timer 1 vẫn chế độ 2.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Quên xóa TF0, lần chờ sau thoát ngay","code":"; Ví dụ 5 (bẫy): quên xóa TF0, lần chờ thứ hai thoát ngay\n; Chip: AT89S52, 12 MHz. Hai lần chờ, mỗi lần định 16 nhịp\n        ORG     0000H\n        MOV     TMOD,#01H\n        MOV     TH0,#0FFH\n        MOV     TL0,#0F0H               ; lần 1: FFF0H\n        SETB    TR0\nCHO1:   JNB     TF0,CHO1\n        CLR     TR0                     ; quên CLR TF0\n        MOV     TH0,#0FFH\n        MOV     TL0,#0F0H               ; lần 2: lẽ ra cũng 16 nhịp\n        SETB    TR0\nCHO2:   JNB     TF0,CHO2                ; TF0 vẫn = 1: thoát ngay\n        CLR     TR0\n        MOV     30H,TL0                 ; 30H = F3H: mới đếm 3 nhịp\n        SJMP    $\n        END\n","note":"Lần chờ đầu đúng 16 nhịp. Vì không xóa TF0, lần chờ thứ hai thấy TF0 = 1 ngay ở vòng hỏi đầu tiên và thoát: timer mới đếm 3 nhịp (TL0 = F3H) thay vì 16. Thêm CLR TF0 sau CLR TR0 rồi chạy lại để so.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: GATE = 1, đếm khi INT0 ở mức 1","code":"; Ví dụ 6: GATE = 1, Timer 0 chỉ đếm khi chân INT0 (P3.2) = 1\n; Chip: AT89S52. Chương trình tự kéo P3.2 lên rồi xuống\n        ORG     0000H\n        MOV     TMOD,#09H               ; Timer 0: GATE = 1, chế độ 1\n        CLR     P3.2                    ; INT0 = 0: chưa cho đếm\n        SETB    TR0                     ; TR0 = 1 nhưng timer vẫn đứng\n        NOP\n        NOP\n        SETB    P3.2                    ; INT0 = 1: bắt đầu đếm\n        NOP\n        NOP\n        NOP\n        CLR     P3.2                    ; INT0 = 0: dừng đếm\n        NOP\n        MOV     30H,TL0                 ; 30H = số chu kỳ INT0 ở mức 1\n        SJMP    $\n        END\n","note":"GATE = 1: dù TR0 = 1, Timer 0 chỉ đếm khi chân INT0 (P3.2) = 1. Chân ở mức 1 từ sau SETB P3.2 tới hết lệnh CLR P3.2: 4 chu kỳ máy, nên 30H = 04H. Trên phần Thời gian, so INT0 và TL0. Có thể giữ nút K1 (P3.2) khi chạy từng bước để giữ chân ở 0.","dev":{"led":true,"btn":true},"fosc":12000000}];
const sim25=makeSim51(document.getElementById("m51-l25"),{id:"s25",presets:PR25,ram:256});
makeEx51(document.getElementById("ex-l25"),"l25",[{"t":"Lắp byte TMOD từ yêu cầu","d":"<p>Ô <code>30H<\/code> chứa chế độ của Timer 0 (0–3), ô <code>31H<\/code> chứa chế độ của Timer 1 (0–3). Ô <code>32H<\/code> chứa các cờ: bit 0 = C/T của Timer 0, bit 1 = GATE của Timer 0, bit 2 = C/T của Timer 1, bit 3 = GATE của Timer 1 (các bit 4–7 bằng 0). Hãy lắp byte TMOD đúng vị trí bit, ghi vào thanh ghi <code>TMOD<\/code> và chép vào ô <code>33H<\/code>. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 01H<\/code>, <code>31H = 02H<\/code>, <code>32H = 00H<\/code> → <code>TMOD = 21H<\/code> (Timer 1 chế độ 2, Timer 0 chế độ 1).<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; chế độ Timer 0\n        ORL     A,31H                   ; SAI: chế độ Timer 1 chưa dời lên\n        ORL     A,32H                   ; SAI: các cờ chưa về đúng bit\n        MOV     TMOD,A\n        MOV     33H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":0,"0x33":238}},"expect":{"iram":{"0x33":33},"regs":{"TMOD":33}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":238}},"expect":{"iram":{"0x33":0},"regs":{"TMOD":0}}},{"setup":{"iram":{"0x30":3,"0x31":3,"0x32":15,"0x33":238}},"expect":{"iram":{"0x33":255},"regs":{"TMOD":255}}},{"setup":{"iram":{"0x30":2,"0x31":1,"0x32":5,"0x33":238}},"expect":{"iram":{"0x33":86},"regs":{"TMOD":86}}},{"setup":{"iram":{"0x30":1,"0x31":1,"0x32":10,"0x33":238}},"expect":{"iram":{"0x33":153},"regs":{"TMOD":153}}},{"setup":{"iram":{"0x30":0,"0x31":2,"0x32":2,"0x33":238}},"expect":{"iram":{"0x33":40},"regs":{"TMOD":40}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":4,"0x33":238}},"expect":{"iram":{"0x33":65},"regs":{"TMOD":65}}}]},"hints":["Nửa thấp TMOD là Timer 0 theo thứ tự GATE, C/T, M1, M0 (bit 3…0); nửa cao là Timer 1 theo cùng thứ tự (bit 7…4).","Chế độ Timer 1 phải dời lên 4 bit: SWAP A đổi chỗ hai nửa byte, nhanh hơn 4 lần RL A.","Mỗi trường phải về đúng vị trí bit trong TMOD: tách bằng ANL, dời bằng lệnh xoay, ghép bằng ORL."],"why":"TMOD xếp hai nửa giống nhau: GATE, C/T, M1, M0 cho Timer 1 ở bit 7–4 và cho Timer 0 ở bit 3–0. Lỗi hay gặp là đặt GATE vào chỗ C/T (test 5) hoặc quên dời chế độ Timer 1 lên nửa cao."},{"t":"Số đếm 13 bit của chế độ 0","d":"<p>Timer 0 chạy ở chế độ 0 (13 bit). Chương trình khác đã chép <code>TH0<\/code> vào ô <code>30H<\/code> và <code>TL0<\/code> vào ô <code>31H<\/code>. Chỉ 5 bit thấp của TL0 thuộc số đếm (Intel ghi 3 bit cao là không xác định). Hãy tính số đếm 13 bit = TH0 × 32 + (TL0 AND 1FH) và ghi vào <code>32H<\/code> (byte cao), <code>33H<\/code> (byte thấp); rồi tính số nhịp còn lại tới khi tràn = 2000H − số đếm, ghi vào <code>34H<\/code> (cao), <code>35H<\/code> (thấp). Ô 30H, 31H giữ nguyên.<\/p><p>Ví dụ: <code>30H = FFH<\/code>, <code>31H = 1CH<\/code> → số đếm <code>1FFCH<\/code> (32H = 1FH, 33H = FCH), còn <code>0004H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H\n        MOV     B,#32\n        MUL     AB                      ; B:A = TH0 x 32\n        ORL     A,31H                   ; ghép TL0 (còn thiếu gì?)\n        MOV     32H,B\n        MOV     33H,A\n        MOV     34H,#00H                ; chưa tính số nhịp còn lại\n        MOV     35H,#00H\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":255,"0x31":28,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":255,"0x31":28,"0x32":31,"0x33":252,"0x34":0,"0x35":4}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":32,"0x35":0}}},{"setup":{"iram":{"0x30":255,"0x31":31,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":255,"0x31":31,"0x32":31,"0x33":255,"0x34":0,"0x35":1}}},{"setup":{"iram":{"0x30":1,"0x31":0,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":0,"0x33":32,"0x34":31,"0x35":224}}},{"setup":{"iram":{"0x30":128,"0x31":229,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":128,"0x31":229,"0x32":16,"0x33":5,"0x34":15,"0x35":251}}},{"setup":{"iram":{"0x30":18,"0x31":52,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":18,"0x31":52,"0x32":2,"0x33":84,"0x34":29,"0x35":172}}},{"setup":{"iram":{"0x30":0,"0x31":31,"0x32":238,"0x33":238,"0x34":238,"0x35":238}},"expect":{"iram":{"0x30":0,"0x31":31,"0x32":0,"0x33":31,"0x34":31,"0x35":225}}}]},"hints":["TH0 × 32 dùng được MUL AB với B = 32: kết quả 16 bit nằm ở B (cao) và A (thấp).","5 bit thấp của A sau phép nhân bằng 0, nên ghép 5 bit của TL0 bằng ORL (sau khi ANL với 1FH).","2000H − số đếm là phép trừ 16 bit có mượn, bắt đầu từ byte thấp."],"why":"Chế độ 0 là bộ đếm 13 bit: TH0 giữ 8 bit cao, TL0 chỉ dùng 5 bit thấp (chia 32). Đếm tối đa 2^13 = 8192 = 2000H nhịp mới tràn. Test 5 có TL0 = E5H: quên AND 1FH thì ra số sai."},{"t":"Đổi Timer 1 sang chế độ 2 mà giữ Timer 0","d":"<p>Timer 0 đang được phần khác của firmware dùng (cấu hình bất kỳ trong nửa thấp TMOD, có thể đang chạy). Hãy chuyển Timer 1 sang <b>bộ định thời chế độ 2<\/b> (GATE = 0, C/T = 0) với giá trị nạp lấy từ ô <code>30H<\/code> (TH1 = TL1 = [30H]) rồi cho Timer 1 chạy (TR1 = 1). Yêu cầu: nửa thấp TMOD, TR0 giữ nguyên; <b>A và B không được đổi<\/b>; cuối cùng chép TMOD mới vào ô <code>31H<\/code>. Toàn chương trình không quá <b>13 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và <b>19 byte<\/b> mã.<\/p><p>Ví dụ: TMOD = 01H, [30H] = F6H → TMOD = 21H, TH1 = F6H, TR1 = 1, [31H] = 21H.<\/p>","start":"        ORG     0000H\n        MOV     TMOD,#20H               ; Timer 1 chế độ 2 (Timer 0 thì sao?)\n        MOV     TH1,30H                 ; giá trị nạp lại\n        MOV     TL1,30H                 ; lần đếm đầu\n        SETB    TR1\n        MOV     31H,TMOD\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":246,"0x31":238},"regs":{"TMOD":1,"TCON":0,"A":0,"B":255}},"expect":{"iram":{"0x31":33},"regs":{"TMOD":33,"TH1":246,"A":0,"B":255},"bits":{"TR1":1,"TR0":0}}},{"setup":{"iram":{"0x30":0,"0x31":238},"regs":{"TMOD":0,"TCON":0,"A":0,"B":255}},"expect":{"iram":{"0x31":32},"regs":{"TMOD":32,"TH1":0,"A":0,"B":255},"bits":{"TR1":1,"TR0":0}}},{"setup":{"iram":{"0x30":56,"0x31":238},"regs":{"TMOD":9,"TCON":16,"A":90,"B":165}},"expect":{"iram":{"0x31":41},"regs":{"TMOD":41,"TH1":56,"A":90,"B":165},"bits":{"TR1":1,"TR0":1}}},{"setup":{"iram":{"0x30":253,"0x31":238},"regs":{"TMOD":213,"TCON":0,"A":165,"B":90}},"expect":{"iram":{"0x31":37},"regs":{"TMOD":37,"TH1":253,"A":165,"B":90},"bits":{"TR1":1,"TR0":0}}},{"setup":{"iram":{"0x30":128,"0x31":238},"regs":{"TMOD":98,"TCON":16,"A":0,"B":255}},"expect":{"iram":{"0x31":34},"regs":{"TMOD":34,"TH1":128,"A":0,"B":255},"bits":{"TR1":1,"TR0":1}}},{"setup":{"iram":{"0x30":1,"0x31":238},"regs":{"TMOD":246,"TCON":0,"A":255,"B":0}},"expect":{"iram":{"0x31":38},"regs":{"TMOD":38,"TH1":1,"A":255,"B":0},"bits":{"TR1":1,"TR0":0}}},{"setup":{"iram":{"0x30":156,"0x31":238},"regs":{"TMOD":49,"TCON":16,"A":60,"B":195}},"expect":{"iram":{"0x31":33},"regs":{"TMOD":33,"TH1":156,"A":60,"B":195},"bits":{"TR1":1,"TR0":1}}}],"maxCyc":13,"maxBytes":19},"hints":["MOV TMOD,#20H xóa luôn nửa của Timer 0. Cần lệnh đọc–sửa–ghi chỉ đụng tới nửa cao.","ANL và ORL có dạng “địa chỉ trực tiếp, #dữ liệu” (3 byte, 2 chu kỳ), sửa thẳng SFR mà không qua A. Dùng A thì phải cất và lấy lại A (PUSH/POP), quá giới hạn chu kỳ.","Giá trị nạp đi vào cả TH1 (nạp lại) và TL1 (lần đầu); có dạng MOV chép thẳng từ ô RAM sang SFR. TCON định địa chỉ bit được."],"why":"TMOD không định địa chỉ bit, nên đổi một timer phải đọc–sửa–ghi cả byte: ANL xóa 4 bit của Timer 1, ORL đặt chế độ 2. Lời giải tham chiếu: 2 + 2 + 2 + 2 + 1 + 2 + 2 = 13 chu kỳ, 19 byte. Code mẫu dùng MOV TMOD,#20H nên chỉ qua test 2 (Timer 0 vốn bằng 0)."}]);

makeQuiz("quiz25","score25",[{"q": "TMOD = 21H. Hai timer được cấu hình thế nào?", "o": ["Timer 0 chế độ 2; Timer 1 chế độ 1", "Timer 1 bộ định thời chế độ 2; Timer 0 bộ định thời chế độ 1", "Timer 1 đếm sự kiện chế độ 1; Timer 0 chế độ 2", "Cả hai timer chế độ 3"], "a": 1, "e": "Nửa cao 2H = 0010B là Timer 1: GATE = 0, C/T = 0, M1 M0 = 10 (chế độ 2). Nửa thấp 1H = 0001B là Timer 0: chế độ 1, bộ định thời."}, {"q": "Timer 0 chế độ 1, nạp TH0:TL0 = 0000H, thạch anh 12 MHz. Bao lâu sau khi TR0 = 1 thì TF0 bật?", "o": ["65,535 ms", "8,192 ms", "786,432 ms", "65,536 ms"], "a": 3, "e": "Từ 0000H phải đếm 65 536 nhịp mới quay về 0000H; mỗi nhịp 12/12 MHz = 1 µs. 8,192 ms là chế độ 0 (13 bit); 786,432 ms là nhân thêm 12, nhầm nhịp thạch anh với chu kỳ máy."}, {"q": "Vì sao lệnh SETB TMOD.0 không dùng được để đặt bit M0 của Timer 0?", "o": ["SETB chỉ dùng cho cổng P0–P3", "TMOD (89H) không định địa chỉ bit; phải dùng ORL TMOD,#01H", "TMOD chỉ ghi được một lần sau reset", "Bit M0 chỉ đổi được khi TR0 = 1"], "a": 1, "e": "Chỉ SFR có địa chỉ chia hết cho 8 (80H, 88H, 90H…) mới định địa chỉ bit. TCON 88H thì được (SETB TR0), TMOD 89H thì không; đổi một phần TMOD bằng ANL/ORL."}, {"q": "Chương trình hỏi vòng JNB TF0,$ rồi chạy tiếp nhưng không có lệnh CLR TF0. Điều gì xảy ra ở lần chờ kế tiếp?", "o": ["TF0 vẫn bằng 1 nên vòng chờ thoát ngay, thời gian trễ gần như bằng 0", "Phần cứng tự xóa TF0 nên vẫn chờ đủ", "Timer dừng hẳn cho tới khi reset", "TF0 tự xóa khi nạp lại TH0, TL0"], "a": 0, "e": "Phần cứng chỉ xóa TF0 khi vào chương trình ngắt Timer 0. Khi hỏi vòng, phần mềm phải CLR TF0; nạp lại TH0/TL0 không đụng tới cờ (ví dụ 5)."}, {"q": "TMOD = 09H (Timer 0: GATE = 1, chế độ 1), TR0 = 1, chân INT0 = 0. Timer 0 làm gì?", "o": ["Đếm bình thường vì TR0 = 1", "Đếm sườn xuống ở chân INT0", "Đứng yên cho tới khi INT0 lên 1", "Đếm sự kiện ở chân T0"], "a": 2, "e": "Với GATE = 1, timer đếm khi TR0 = 1 VÀ INT0 = 1. C/T = 0 nên nguồn xung vẫn là chu kỳ máy; chân INT0 chỉ làm công tắc (ví dụ 6)."}]);

